269	                                                   int sendTimeoutSecs)
270	    {
271	        {
272	            std::lock_guard<std::mutex> lock(_configMutex);
273	            _ws.configure(
274	                _perMessageDeflateOptions, _socketTLSOptions, _enablePong, _pingIntervalSecs);
275	        }
276	
277	        WebSocketInitResult status = _ws.connectToSocket(
278	            std::move(socket), timeoutSecs, enablePerMessageDeflate, request, sendTimeoutSecs);
279	        if (!status.success)
280	        {
281	            return status;
282	        }
283	
284	        _onMessageCallback(
285	            ix::make_unique<WebSocketMessage>(WebSocketMessageType::Open,
286	                                              emptyMsg,
287	                                              0,
288	                                              WebSocketErrorInfo(),
289	                                              WebSocketOpenInfo(status.uri, status.headers),
290	                                              WebSocketCloseInfo()));
291	
292	        if (_pingIntervalSecs > 0)
293	        {
