/*
 *  IXWebSocketPerMessageDeflateCodecTest.cpp
 *  Author: Benjamin Sergeant
 *  Copyright (c) 2020 Machine Zone. All rights reserved.
 *
 *  make build_test && build/test/ixwebsocket_unittest per-message-deflate-codec
