171	        server.setOnClientMessageCallback(
172	            [&receivedCloseCode, &receivedCloseReason, &receivedCloseRemote, &mutexWrite](
173	                std::shared_ptr<ConnectionState> connectionState,
174	                WebSocket& /*webSocket*/,
175	                const ix::WebSocketMessagePtr& msg) {
176	                auto remoteIp = connectionState->getRemoteIp();
177	                if (msg->type == ix::WebSocketMessageType::Open)
178	                {
179	                    TLogger() << "New server connection";
180	                    TLogger() << "remote ip: " << remoteIp;
181	                    TLogger() << "id: " << connectionState->getId();
182	                    TLogger() << "Uri: " << msg->openInfo.uri;
183	                    TLogger() << "Headers:";
184	                    for (auto it : msg->openInfo.headers)
185	                    {
186	                        TLogger() << it.first << ": " << it.second;
187	                    }
188	                }
189	                else if (msg->type == ix::WebSocketMessageType::Close)
190	                {
191	                    std::stringstream ss;
192	                    ss << "Server closed connection(" << msg->closeInfo.code << ","
193	                       << msg->closeInfo.reason << ")";
194	                    log(ss.str());
195	
196	                    std::lock_guard<std::mutex> lck(mutexWrite);
197	
198	                    receivedCloseCode = msg->closeInfo.code;
199	                    receivedCloseReason = std::string(msg->closeInfo.reason);
200	                    receivedCloseRemote = msg->closeInfo.remote;
201	                }
202	            });
203	
204	        auto res = server.listen();
205	        if (!res.first)
206	        {
207	            log(res.second);
208	            return false;
209	        }
210	
211	        server.start();
212	        return true;
