// Encode a frame (mask if maskKey true)
std::string encodeFrame(uint8_t opcode, bool fin, bool rsv1, const std::string& payload, bool mask)
{
    std::string out;
    uint8_t b0 = opcode & 0x0f;
    if (fin) b0 |= 0x80;
    if (rsv1) b0 |= 0x40;
    out.push_back((char)b0);
    uint8_t maskBit = mask ? 0x80 : 0;
