bool readExact(int fd, char* buf, size_t n) {
    size_t got = 0;
    while (got < n) {
        ssize_t r = recv(fd, buf+got, n-got, 0);
        if (r <= 0) return false;
        got += r;
    }
    return true;
}

bool readFrame(int fd, Frame& f) {
    char hdr[2];
    if (!readExact(fd, hdr, 2)) return false;
    f.fin = hdr[0] & 0x80; f.rsv1 = hdr[0] & 0x40; f.opcode = hdr[0] & 0x0f;
