if (f.opcode == 0x8)
{
    obs->gotClose = true;
    if (f.payload.size() >= 2)
    {
        obs->closeCode =
            (uint16_t)(((uint16_t)(uint8_t) f.payload[0] << 8) |
                       (uint8_t) f.payload[1]);
        obs->closeReason = f.payload.substr(2);
    }
    // Echo the close frame back to complete the closing handshake
    sendAll(fd, encodeFrame(0x8, true, false, f.payload, false));
    break;
}

